/**
 * Joyful Jack's mechanical model, as UHD: printed, cut and bought parts with their mating interfaces
 * (bolt patterns, bearing seats, shafts, faces, each with its frame), fastener-stack harnesses for every
 * bolted joint, and the hardware modules the stack's hardware-cad gives nominal bodies.
 *
 * The data is generated by cad/mech/build.py (build123d) into src/mech/mech.json (parts: features in each
 * part's own frame, body files, masses) and src/mech/tier-<t>.json (instances, mates with their stacks).
 * This file only shapes it into ModuleDefs; nothing numeric is typed here.
 */
import type { ArtifactDef, InterfaceDef, ModuleDef } from "@deltarobotics/uhd";
import { AxialFace, Bearing, BearingSeat, BoltPattern, Shaft, Thread } from "@deltarobotics/uhd";
import { hardwareCadArtifacts } from "@protoboardai/ext-frame-cad/artifacts";
import DB from "./mech.json" with { type: "json" };

type Frame = { origin: number[]; normal: number[]; xAxis: number[]; symmetryDeg?: number };
type Feature = { name: string; kind: string; frame: Frame; params: Record<string, unknown> };
export type PartEntry = {
  id: string;
  name: string;
  category: string;
  material: string;
  mass_g: number | null;
  source: string;
  notes: string;
  meta: Record<string, unknown>;
  features: Record<string, Feature>;
  body?: { dir: string; step: string; glb: string; manifest: string; stl?: string } | null;
  hardware?: Record<string, unknown>;
};

export const PARTS = (DB as unknown as { parts: Record<string, PartEntry> }).parts;

const DIAMETER: Record<string, number> = { "1/4-20": 6.35, "#8 wood screw": 4.2, "#4 wood screw": 2.8, "1 in NPT": 33.4 };

/** Nominal diameter of a fastener designation (M3 -> 3, #8 wood screw -> 4.2). */
export function fastenerDiameter(f: string): number {
  if (f in DIAMETER) return DIAMETER[f];
  const m = /^M(\d+(?:\.\d+)?)/.exec(f);
  if (!m) throw new Error(`fastener designation "${f}" not understood`);
  return Number(m[1]);
}

function geometry(f: Frame) {
  return { frame: { origin: f.origin as [number, number, number], normal: f.normal as [number, number, number], xAxis: f.xAxis as [number, number, number], ...(f.symmetryDeg ? { symmetryDeg: f.symmetryDeg } : {}) } };
}

/** One part feature as a UHD interface with its frame. */
export function featureInterface(id: string, f: Feature): InterfaceDef[] {
  const p = f.params;
  let made: InterfaceDef[];
  switch (f.kind) {
    case "bolt_pattern": {
      const fastener = String(p.fastener ?? "M3");
      const role = (p.role === "structure" ? "structure" : "component") as "structure" | "component";
      const base = { id, name: f.name, role, fastener, fastenerDiameterMm: fastenerDiameter(fastener), threaded: Boolean(p.threaded) };
      const shape = String(p.shape ?? "positions");
      const count = Number(p.count ?? 0);
      if (shape === "positions" || (shape === "circle" && count === 1)) {
        const pos = (p.positions as number[][] | undefined) ?? [[0, 0]];
        if (pos.length !== 1 || pos[0][0] !== 0 || pos[0][1] !== 0) throw new Error(`${id}: only a single hole on the frame origin is supported as positions`);
        made = [BoltPattern({ ...base, shape: "circle", spacingMm: 0, holeCount: 1 })];
      } else if (shape === "row") {
        made = [BoltPattern({ ...base, shape: "row", pitchMm: Number(p.spacing) / (count - 1), holeCount: count })];
      } else if (shape === "rectangle") {
        made = [BoltPattern({ ...base, shape: "rectangle", spacingMm: Number(p.spacing), spacingYmm: Number(p.spacing_y ?? p.spacing), holeCount: count })];
      } else if (shape === "circle") {
        made = [BoltPattern({ ...base, shape: "circle", spacingMm: Number(p.spacing), holeCount: count })];
      } else throw new Error(`${id}: bolt pattern shape ${shape}`);
      break;
    }
    case "bearing_seat":
      made = [BearingSeat({ id, name: f.name, odMm: Number(p.od), depthMm: Number(p.depth ?? 0) || undefined, retention: (p.retention as "press" | "shoulder" | undefined) ?? "shoulder", kinds: ["ball"] })];
      break;
    case "bearing":
      made = Bearing({ id, name: f.name, kind: "ball", boreMm: Number(p.bore), odMm: Number(p.od), widthMm: Number(p.width), bore: false });
      break;
    case "shaft":
      made = [Shaft({ id, name: f.name, role: "bidirectional", gender: (p.gender as "shaft" | "bore") ?? "shaft", diameterMm: Number(p.diameter), ...(p.thread ? { thread: String(p.thread) } : {}) })];
      break;
    default:
      // faces, belt planes, anchors: an annular contact face (turns with its part)
      made = [AxialFace({ id, name: f.name, odMm: 200, idMm: 0, kind: f.kind === "belt" ? "hub" : "housing", note: `contact face (${f.kind})` })];
  }
  return made.map((i) => ({ ...i, geometry: geometry(f.frame) }));
}

function bodyArtifacts(e: PartEntry): ArtifactDef[] {
  if (!e.body) return [];
  const b = e.body;
  const gen = "cad/mech/build.py";
  return [
    { id: "cad_source", name: `${e.id} generator`, type: "cad", role: "source", format: "py", filePath: gen },
    { id: "cad_step", name: `${e.name} (STEP)`, type: "3d_model", role: "body", format: "step", units: "mm", filePath: b.step, provenance: { generatedFrom: "cad_source", tool: "build123d 0.13.0" } },
    { id: "cad_glb", name: `${e.name} (GLB)`, type: "3d_model", role: "body", format: "glb", units: "m", filePath: b.glb, provenance: { generatedFrom: "cad_step", tool: "build123d 0.13.0" } },
    { id: "cad_manifest", name: `${e.name} manifest`, type: "cad", role: "source", format: "json", filePath: b.manifest, provenance: { generatedFrom: "cad_step", tool: "build123d 0.13.0" } },
    ...(b.stl ? [{ id: "cad_stl", name: `${e.name} (STL, for printing)`, type: "3d_model", role: "fabrication", format: "stl", units: "mm", filePath: b.stl, provenance: { generatedFrom: "cad_step", tool: "build123d 0.13.0" } } as ArtifactDef] : []),
  ] as ArtifactDef[];
}

const CATEGORY: Record<string, string[]> = {
  printed: ["mechanical.structure"],
  cut: ["mechanical.structure"],
  bought: ["mechanical.structure"],
  vendor: ["mechanical.structure"],
};

/** A printed, cut or bought mechanical part. */
export function mechPart(id: string, extra: Partial<ModuleDef> = {}): ModuleDef {
  const e = PARTS[id];
  if (!e) throw new Error(`mech.json has no part ${id}`);
  const interfaces = Object.entries(e.features).flatMap(([fid, f]) => featureInterface(fid, f));
  const meta = e.meta ?? {};
  const fabricated = e.category === "printed" || e.category === "cut";
  return {
    id: e.id,
    name: e.name,
    kind: "module",
    version: "0.1.0",
    description: `${e.name}.${e.notes ? " " + e.notes : ""}${meta.print ? ` Print: ${meta.print}.` : ""}`,
    categories: CATEGORY[e.category] ?? ["mechanical.structure"],
    tags: ["mechanical", e.category, ...(fabricated ? ["designed-here"] : [])],
    ...(meta.part_number ? { part_number: String(meta.part_number) } : {}),
    interfaces,
    artifacts: bodyArtifacts(e),
    domains: [
      {
        domain: "mechanical",
        ...(e.mass_g ? { weight_g: Math.round(e.mass_g * 10) / 10 } : {}),
        metadata: { material: e.material, process: fabricated ? (e.category === "printed" ? "3d_print" : "cut") : "bought", ...(meta.print ? { print: meta.print } : {}), source: e.source },
      },
    ],
    traits: [
      ...(e.source ? [{ type: "usage_note", params: { note: e.source } }] : []),
      ...(meta.inserts && (meta.inserts as unknown[]).length ? [{ type: "usage_note", params: { note: `Heat-set inserts pressed in before assembly: ${(meta.inserts as [number, number][]).map(([d, n]) => `${n} x M${d}`).join(", ")}.` } }] : []),
    ],
    ...extra,
  } as ModuleDef;
}

/** Add a part's mechanical interfaces and body to an existing (electrical) definition: a servo, a buck, a dock. */
export function withMech(def: ModuleDef, mechId: string): ModuleDef {
  const e = PARTS[mechId];
  if (!e) throw new Error(`mech.json has no part ${mechId}`);
  const have = new Set(def.interfaces.map((i) => i.id));
  const clash = Object.keys(e.features).filter((fid) => have.has(fid));
  if (clash.length) throw new Error(`${def.id}: mechanical feature ids ${clash.join(", ")} clash with its interfaces`);
  const added = Object.entries(e.features).flatMap(([fid, f]) => featureInterface(fid, f));
  return {
    ...def,
    interfaces: [...def.interfaces, ...added],
    artifacts: [...(def.artifacts ?? []), ...bodyArtifacts(e)],
    traits: [...(def.traits ?? []), { type: "usage_note", params: { note: `Body and mounting faces: ${e.source}` } }],
  };
}

/** A screw, nut, insert, washer, T-nut or shoulder screw, with the sizes hardware-cad builds its nominal body from. */
export function hardwarePart(id: string): ModuleDef {
  const e = PARTS[id];
  const h = (e.hardware ?? e.meta) as Record<string, number | string>;
  const kind = String(h.kind);
  const tagKind = kind === "insert" ? "spacer" : kind;   // a heat-set insert is drawn as a sleeve (no thread form)
  const d = Number(h.diameter);
  const len = Number(h.length);
  const designation = d === 6.35 ? "1/4-20" : d === 4.2 ? "#8" : d === 2.8 ? "#4" : `M${d}`;
  const thread = Thread({
    id: "thread",
    name: `${designation} thread`,
    gender: kind === "screw" ? "external" : "internal",
    designation,
    diameterMm: d,
    lengthMm: len,
    kind: kind === "screw" ? "screw" : kind === "insert" ? "insert" : "nut",
  } as Parameters<typeof Thread>[0]);
  const dir = `parts/local/mech/hw/${id}`;
  const meta: Record<string, unknown> = {};
  if (kind === "screw") {
    meta.head_diameter_mm = Number(h.head_diameter);
    meta.head_height_mm = Number(h.head_height);
  } else {
    meta.outer_mm = Number(h.outer ?? d * 1.6);
    if (h.bore) meta.bore_mm = Number(h.bore);
  }
  return {
    id,
    name: e.name,
    kind: "module",
    version: "0.1.0",
    description: `${e.name}.${h.standard ? ` ${h.standard}.` : ""}`,
    categories: ["mechanical.fastener"],
    tags: ["fastener", tagKind, ...(kind === "insert" ? ["heat-set-insert"] : [])],
    interfaces: [{ ...thread, parameters: [...(thread.parameters ?? []), { id: "length", name: "Length", value: len, unit: "mm" }] } as InterfaceDef],
    artifacts: hardwareCadArtifacts({ dir, name: id }),
    domains: [{ domain: "mechanical", metadata: { ...meta, material: e.material === "brass" ? "brass" : "steel" }, material: { density_g_cm3: e.material === "brass" ? 8.5 : 7.85 } }],
    traits: [{ type: "assumption", params: { field: "geometry", value: "nominal standard sizes", reason: e.source || "ISO nominal dimensions" } }],
  } as unknown as ModuleDef;
}

type StackItem = { part: string; at: number; direction: number; torque_nm: number | null; torque_note: string; positions?: number[][] };

/** A fastener stack as a harness module: its hardware as children with quantities, and where each sits. */
export function stackHarness(id: string, name: string, stack: StackItem[], holes: number): ModuleDef {
  const counts = new Map<string, number>();
  for (const s of stack) counts.set(s.part, (counts.get(s.part) ?? 0) + (s.positions ? s.positions.length : holes));
  const childId = (part: string) => part.replace(/[^a-z0-9]+/gi, "_");
  return {
    id,
    name,
    kind: "harness",
    topology: "bus",
    description: `${name}: ${stack.map((s) => `${PARTS[s.part]?.name ?? s.part} at ${s.at} mm`).join("; ")}.`,
    tags: ["fastener-stack"],
    interfaces: [],
    children: [...counts.entries()].map(([part, quantity]) => ({ id: childId(part), moduleDefId: part, name: PARTS[part]?.name ?? part, quantity })),
    links: [],
    fastenerStack: stack.map((s) => ({
      child: childId(s.part),
      atMm: s.at,
      ...(s.direction === -1 ? { direction: -1 as const } : {}),
      ...(s.positions ? { positions: s.positions.map((p) => [p[0], p[1]] as [number, number]) } : {}),
      ...(s.torque_nm != null
        ? { torque: { torqueNm: s.torque_nm, ...(s.torque_note?.startsWith("assumption") ? { assumption: s.torque_note } : { assumption: `assumption: ${s.torque_note}` }) } }
        : {}),
    })),
  } as unknown as ModuleDef;
}
